

CREATE TABLE covid_stats (
    country VARCHAR(100),
    Confirmed FLOAT,
    Deaths FLOAT,
    Recovered FLOAT,
    Active FLOAT,
    `New cases` FLOAT,
    `New deaths` FLOAT,
    `New recovered` FLOAT,
    continent VARCHAR(50),
    total_confirmed FLOAT,
    total_deaths FLOAT,
    total_recovered FLOAT,
    active_cases FLOAT,
    serious_or_critical FLOAT,
    total_tests FLOAT,
    population FLOAT,
    date_timestamp BIGINT
);


